begin;

-- A Source change/removal is a new opportunity and plan revision. Historical
-- evidence, recipes, candidates, selections, Sources, and links remain intact;
-- current readback stops projecting them because they reference the predecessor
-- opportunity/plan revision.
create or replace function tongs.reassign_reference_visual_source(
  p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,
  p_expected_opportunity_revision_id uuid,p_expected_opportunity_revision bigint,
  p_source_revision_id uuid,p_workpiece_source_link_revision_id uuid,
  p_operation_id text,p_operation_fingerprint text,p_actor_id uuid
) returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
#variable_conflict use_column
declare receipt tongs.reference_visual_operation_receipts%rowtype; seq tongs.reference_visual_plan_sequences%rowtype; old_plan tongs.reference_visual_plan_revisions%rowtype; old_opp tongs.reference_visual_opportunity_revisions%rowtype; src tongs.source_revisions%rowtype; link_rev tongs.workpiece_source_link_revisions%rowtype; new_plan tongs.reference_visual_plan_revisions%rowtype; new_opp tongs.reference_visual_opportunity_revisions%rowtype; member_rev tongs.reference_visual_plan_membership%rowtype; plan_hash text; opportunity_hash text; immutable_hash text; result jsonb; new_status text;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into receipt from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;
 if found then if receipt.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return receipt.receipt_json;end if;
 if (p_source_revision_id is null)<>(p_workpiece_source_link_revision_id is null) then return jsonb_build_object('disposition','source_and_link_must_match');end if;
 new_status:=case when p_source_revision_id is null then 'unresolved' else 'linked' end;
 select * into seq from tongs.reference_visual_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 select o.* into old_opp from tongs.reference_visual_plan_membership m join tongs.reference_visual_opportunity_revisions o on o.id=m.opportunity_revision_id where m.plan_revision_id=seq.current_plan_revision_id and m.opportunity_id=p_opportunity_id;
 if not found or old_opp.id is distinct from p_expected_opportunity_revision_id or old_opp.revision<>p_expected_opportunity_revision then return jsonb_build_object('disposition','opportunity_revision_conflict');end if;
 if p_source_revision_id is not null then
  select * into src from tongs.source_revisions where id=p_source_revision_id and workspace_id=p_workspace_id;
  select * into link_rev from tongs.workpiece_source_link_revisions where id=p_workpiece_source_link_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=src.id;
  if src.id is null or link_rev.id is null then return jsonb_build_object('disposition','canonical_source_evidence_required');end if;
  if old_opp.source_revision_id=src.id and old_opp.workpiece_source_link_revision_id=link_rev.id then return jsonb_build_object('disposition','source_unchanged');end if;
 elsif old_opp.source_status='unresolved' then return jsonb_build_object('disposition','source_already_unresolved');end if;
 select * into old_plan from tongs.reference_visual_plan_revisions where id=seq.current_plan_revision_id;
 plan_hash:=encode(extensions.digest(convert_to(jsonb_build_object('previous_plan',old_plan.content_hash,'source_transition_opportunity_revision',old_opp.id,'source_status',new_status,'source_revision',src.id,'source_link_revision',link_rev.id)::text,'UTF8'),'sha256'),'hex');
 immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',plan_hash,'revision',old_plan.revision+1,'previous_revision_id',old_plan.id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by) values(p_workspace_id,p_workpiece_id,old_plan.revision+1,old_plan.id,old_plan.revision,old_plan.script_approval_id,old_plan.script_approval_revision,old_plan.script_content_hash,old_plan.contract_version,plan_hash,immutable_hash,p_actor_id) returning * into new_plan;
 opportunity_hash:=encode(extensions.digest(convert_to(jsonb_build_object('previous',old_opp.content_hash,'source_status',new_status,'source_revision',src.id,'source_link_revision',link_rev.id)::text,'UTF8'),'sha256'),'hex');
 immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',opportunity_hash,'revision',old_opp.revision+1,'previous_revision_id',old_opp.id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_opportunity_revisions(opportunity_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,source_status,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,visual_subtype,context_before,context_focus,context_after,citation_anchor_json,document_locator_json,media_range_json,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,content_hash,immutable_revision_hash,created_by)
 select opportunity_id,workspace_id,workpiece_id,revision+1,id,revision,new_plan.id,new_plan.revision,script_approval_id,script_approval_revision,new_status,src.id,src.revision,link_rev.id,link_rev.revision,visual_subtype,context_before,context_focus,context_after,citation_anchor_json,document_locator_json,media_range_json,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,opportunity_hash,immutable_hash,p_actor_id from tongs.reference_visual_opportunity_revisions where id=old_opp.id returning * into new_opp;
 for member_rev in select * from tongs.reference_visual_plan_membership where plan_revision_id=old_plan.id order by ordinal loop insert into tongs.reference_visual_plan_membership values(new_plan.id,p_workspace_id,p_workpiece_id,new_plan.revision,member_rev.ordinal,member_rev.opportunity_id,case when member_rev.opportunity_id=p_opportunity_id then new_opp.id else member_rev.opportunity_revision_id end,case when member_rev.opportunity_id=p_opportunity_id then new_opp.revision else member_rev.opportunity_revision end);end loop;
 update tongs.reference_visual_plan_sequences set current_plan_revision_id=new_plan.id,current_plan_revision=new_plan.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 result:=jsonb_build_object('disposition','committed','source_status',new_status,'plan_revision',to_jsonb(new_plan),'opportunity_revision',to_jsonb(new_opp));
 insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'source_fulfillment',p_workspace_id,p_workpiece_id,'committed',new_opp.id,result,p_actor_id,now());return result;
end$$;

create or replace function tongs.reassign_reference_clip_source(
  p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,
  p_expected_opportunity_revision_id uuid,p_expected_opportunity_revision bigint,
  p_source_revision_id uuid,p_workpiece_source_link_revision_id uuid,
  p_operation_id text,p_operation_fingerprint text,p_actor_id uuid
) returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
#variable_conflict use_column
declare prior jsonb; seq tongs.reference_clip_plan_sequences%rowtype; old_plan tongs.reference_clip_plan_revisions%rowtype; old_opp tongs.reference_clip_opportunity_revisions%rowtype; src tongs.source_revisions%rowtype; link_rev tongs.workpiece_source_link_revisions%rowtype; new_plan tongs.reference_clip_plan_revisions%rowtype; new_opp tongs.reference_clip_opportunity_revisions%rowtype; member_rev tongs.reference_clip_plan_membership%rowtype; plan_hash text; opportunity_hash text; immutable_hash text; result jsonb; new_status text;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select receipt_json into prior from tongs.reference_clip_operation_receipts where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint;if found then return prior;end if;if exists(select 1 from tongs.reference_clip_operation_receipts where operation_id=p_operation_id)then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 if (p_source_revision_id is null)<>(p_workpiece_source_link_revision_id is null) then return jsonb_build_object('disposition','source_and_link_must_match');end if;new_status:=case when p_source_revision_id is null then 'unresolved' else 'linked' end;
 select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 select o.* into old_opp from tongs.reference_clip_plan_membership m join tongs.reference_clip_opportunity_revisions o on o.id=m.opportunity_revision_id where m.plan_revision_id=seq.current_plan_revision_id and m.opportunity_id=p_opportunity_id;
 if not found or old_opp.id is distinct from p_expected_opportunity_revision_id or old_opp.revision<>p_expected_opportunity_revision then return jsonb_build_object('disposition','opportunity_revision_conflict');end if;
 if p_source_revision_id is not null then select * into src from tongs.source_revisions where id=p_source_revision_id and workspace_id=p_workspace_id;select * into link_rev from tongs.workpiece_source_link_revisions where id=p_workpiece_source_link_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=src.id;if src.id is null or link_rev.id is null then return jsonb_build_object('disposition','canonical_source_evidence_required');end if;if old_opp.source_revision_id=src.id and old_opp.workpiece_source_link_revision_id=link_rev.id then return jsonb_build_object('disposition','source_unchanged');end if;elsif old_opp.source_status='unresolved' then return jsonb_build_object('disposition','source_already_unresolved');end if;
 select * into old_plan from tongs.reference_clip_plan_revisions where id=seq.current_plan_revision_id;plan_hash:=encode(extensions.digest(convert_to(jsonb_build_object('previous_plan',old_plan.content_hash,'source_transition_opportunity_revision',old_opp.id,'source_status',new_status,'source_revision',src.id,'source_link_revision',link_rev.id)::text,'UTF8'),'sha256'),'hex');immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('hash',plan_hash,'revision',old_plan.revision+1,'previous',old_plan.id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by)values(p_workspace_id,p_workpiece_id,old_plan.revision+1,old_plan.id,old_plan.revision,old_plan.script_approval_id,old_plan.script_approval_revision,old_plan.script_content_hash,old_plan.contract_version,plan_hash,immutable_hash,p_actor_id)returning * into new_plan;
 opportunity_hash:=encode(extensions.digest(convert_to(jsonb_build_object('previous',old_opp.content_hash,'source_status',new_status,'source_revision',src.id,'source_link_revision',link_rev.id)::text,'UTF8'),'sha256'),'hex');immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('hash',opportunity_hash,'plan',new_plan.id,'opportunity',old_opp.opportunity_id,'revision',old_opp.revision+1)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_opportunity_revisions(opportunity_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,source_status,source_id,source_revision_id,source_revision,workpiece_source_link_id,workpiece_source_link_revision_id,workpiece_source_link_revision,context_before,context_focus,context_after,citation_anchor_json,media_range_json,narrative_purpose,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,content_hash,immutable_revision_hash,created_by)
 select opportunity_id,workspace_id,workpiece_id,revision+1,id,revision,new_plan.id,new_plan.revision,script_approval_id,script_approval_revision,new_status,src.source_id,src.id,src.revision,link_rev.link_id,link_rev.id,link_rev.revision,context_before,context_focus,context_after,citation_anchor_json,case when new_status='linked' then link_rev.media_range_json else media_range_json end,narrative_purpose,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,opportunity_hash,immutable_hash,p_actor_id from tongs.reference_clip_opportunity_revisions where id=old_opp.id returning * into new_opp;
 for member_rev in select * from tongs.reference_clip_plan_membership where plan_revision_id=old_plan.id order by ordinal loop insert into tongs.reference_clip_plan_membership values(new_plan.id,p_workspace_id,p_workpiece_id,new_plan.revision,member_rev.ordinal,member_rev.opportunity_id,case when member_rev.opportunity_id=p_opportunity_id then new_opp.id else member_rev.opportunity_revision_id end,case when member_rev.opportunity_id=p_opportunity_id then new_opp.revision else member_rev.opportunity_revision end);end loop;
 update tongs.reference_clip_plan_sequences set current_plan_revision_id=new_plan.id,current_plan_revision=new_plan.revision,updated_at=now()where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 result:=jsonb_build_object('disposition','committed','source_status',new_status,'plan_revision',to_jsonb(new_plan),'opportunity_revision',to_jsonb(new_opp));insert into tongs.reference_clip_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,opportunity_id,state,result_plan_revision_id,receipt_json,created_by)values(p_operation_id,p_operation_fingerprint,'source_fulfillment',p_workspace_id,p_workpiece_id,p_opportunity_id,'committed',new_plan.id,result,p_actor_id);return result;
end$$;

revoke all on function tongs.reassign_reference_visual_source(uuid,uuid,uuid,uuid,bigint,uuid,uuid,text,text,uuid),tongs.reassign_reference_clip_source(uuid,uuid,uuid,uuid,bigint,uuid,uuid,text,text,uuid) from public,anon;
grant execute on function tongs.reassign_reference_visual_source(uuid,uuid,uuid,uuid,bigint,uuid,uuid,text,text,uuid),tongs.reassign_reference_clip_source(uuid,uuid,uuid,uuid,bigint,uuid,uuid,text,text,uuid) to authenticated,service_role;

notify pgrst,'reload schema';
commit;
